using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Settings;[Authorize]public sealed class UsersModel(OrcaFacilDbContext db,ICurrentAccountService current):PageModel{public IReadOnlyList<Row> Members{get;private set;}=[];public sealed record Row(Guid Id,string Name,string Email,string Role,string Status,DateTime? LastAccess);public async Task<IActionResult> OnGetAsync(CancellationToken ct){if(!current.AccountId.HasValue||!await current.HasPermissionAsync("members.manage",ct))return Forbid();Members=await(from m in db.AccountMembers.AsNoTracking() join u in db.Users.AsNoTracking() on m.UserId equals u.Id where m.AccountId==current.AccountId&&!m.IsDeleted&&!u.IsDeleted select new Row(m.Id,u.Name,u.Email,m.RoleCode,m.Status.ToString(),u.LastSeenAt??u.LastLoginAt)).ToListAsync(ct);return Page();}}
